{
  "title": "Cusco Centro, Close and Cozy",
  "summary": "A relaxed Sunday around the heart of Cusco, with market colours, the grand plaza, and meals a short stroll apart.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "We begin where Cusco wakes: fruit, flowers, and the hum of local life, all without spending a sol."
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle wander around the plaza, just steps from the market, to let the city settle in around us."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "A light, easy lunch nearby, kind to the budget and close enough that no one has to hurry."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "The cathedral waits just off the plaza, so we step inside for a little history without a long ride."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner stays in the same quarter, a warm end to a day that never asked us to rush."
    }
  ]
}
